-- File: 03-patch-status.sql
-- Purpose: 推進檢舉狀態（pending → investigating → verified / dismissed），同時支援 seller_violation_reports 與 food_safety_reports
-- When to use: admin UI 故障時，admin 直接調整檢舉狀態以推進處理流程
-- Variables to fill:
--   :report_table   — 'seller_violation_reports' 或 'food_safety_reports'（決定要改哪張表）
--   :report_id      — 該表的 id (bigint TSID)
--   :new_status     — 'investigating' / 'verified' / 'dismissed'
--   :resolution     — 結案時的 admin_resolution_summary（pending → investigating 階段可填 NULL）
-- Audit: 執行後將完整 SQL + 結果貼到 Discord #food-safety-actions channel 留紀錄
-- Generated by B-169 (issue #722) — 2026-05-07
--
-- 狀態機合法轉移（兩表共用）：
--   pending       → investigating | dismissed
--   investigating → verified | dismissed
--   verified / dismissed 為終態，禁改
--
-- 註：psql client 無法用一個變數動態切表名 → 本檔提供兩個 BEGIN 區塊，
--     admin 依 :report_table 值執行對應那一段，另一段請整段註解掉或跳過。

-- =============================================================================
-- A. 若 :report_table = 'seller_violation_reports' 走這段
-- =============================================================================
BEGIN;

UPDATE seller_violation_reports
SET
    status = :'new_status',
    investigating_at = CASE
        WHEN :'new_status' = 'investigating' AND investigating_at IS NULL THEN now()
        ELSE investigating_at
    END,
    resolved_at = CASE
        WHEN :'new_status' IN ('verified', 'dismissed') THEN now()
        ELSE resolved_at
    END,
    admin_resolution_summary = CASE
        WHEN :'new_status' IN ('verified', 'dismissed') THEN :'resolution'
        ELSE admin_resolution_summary
    END,
    updated_at = now()
WHERE id = :report_id
  AND status = CASE :'new_status'
        WHEN 'investigating' THEN 'pending'
        WHEN 'verified'      THEN 'investigating'
        WHEN 'dismissed'     THEN status  -- pending or investigating 皆可
        ELSE status
      END
  -- 額外保護：終態禁改
  AND status NOT IN ('verified', 'dismissed')
RETURNING id, status, investigating_at, resolved_at, admin_resolution_summary;

-- 驗證
SELECT
    id, target_seller_id, category, severity, status,
    investigating_at, resolved_at, admin_resolution_summary, created_at, updated_at
FROM seller_violation_reports
WHERE id = :report_id;

ROLLBACK; -- 確認後改 COMMIT;


-- =============================================================================
-- B. 若 :report_table = 'food_safety_reports' 走這段
-- =============================================================================
BEGIN;

UPDATE food_safety_reports
SET
    status = :'new_status',
    investigating_at = CASE
        WHEN :'new_status' = 'investigating' AND investigating_at IS NULL THEN now()
        ELSE investigating_at
    END,
    resolved_at = CASE
        WHEN :'new_status' IN ('verified', 'dismissed') THEN now()
        ELSE resolved_at
    END,
    admin_resolution_summary = CASE
        WHEN :'new_status' IN ('verified', 'dismissed') THEN :'resolution'
        ELSE admin_resolution_summary
    END,
    updated_at = now()
WHERE id = :report_id
  AND status = CASE :'new_status'
        WHEN 'investigating' THEN 'pending'
        WHEN 'verified'      THEN 'investigating'
        WHEN 'dismissed'     THEN status
        ELSE status
      END
  AND status NOT IN ('verified', 'dismissed')
  -- 額外保護：食安檢舉進 investigating 之前必須先 ack（02-ack.sql）
  AND (:'new_status' <> 'investigating' OR acknowledged_at IS NOT NULL)
RETURNING id, status, acknowledged_at, investigating_at, resolved_at, admin_resolution_summary;

-- 驗證
SELECT
    id, target_seller_id, target_product_id, status,
    acknowledged_at, acknowledged_by_admin_id,
    investigating_at, resolved_at, admin_resolution_summary,
    fda_reported_at, created_at, updated_at
FROM food_safety_reports
WHERE id = :report_id;

ROLLBACK; -- 確認後改 COMMIT;
